function tipEvidence(t){if(t.verification)return'後續核對回覆：'+t.verification.text;if(!t.evidenceLevel)return'只有匿名片段，日期與原始附件尚未核對；目前不能確認指控。';const texts={issue:['兩份摘要出現相同案號與金額，但仍缺原始請款附件，尚不能定論。','本局原始附件確認有重複請款，已列為待正式處理的帳目問題；是否涉及犯罪仍不能自行定罪。'],false:['來信截圖與帳目日期不一致，可能是不同版本或年度，需要核對原件。','核對後發現是不同年度的同名活動，原來的重複請款指控不成立。'],unclear:['部分金額對不上，但關鍵附件缺失；只能說有待核對，不能定論。','已查到可取得的資料，關鍵附件仍缺失，無法證實或排除帳目問題。']};return texts[t.truth][Math.min(t.evidenceLevel,2)-1];}
