function correctionText(topic){if(topic==='sanitation')return'更正：我不能保證全市根除，公開保留原話';return ['welfare','senior'].includes(topic)?'更正：我不能保證核定或給付，公開保留原話':'更正：我不能保證工期，公開保留原話';}
